<?php
require_once __DIR__ . '/../includes/auth.php';
require_login();
$user = current_user(); $pdo = db(); $errors = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? '';
    if ($action === 'add') {
        $name = trim($_POST['name'] ?? ''); $balance = (float)($_POST['balance'] ?? 0);
        if ($name === '') $errors[] = 'Nama rekening wajib diisi.';
        elseif ($balance < 0) $errors[] = 'Saldo awal tidak boleh negatif.';
        else { $stmt=$pdo->prepare("INSERT INTO accounts(user_id,name,current_balance,status) VALUES(?,?,?,'active')"); $stmt->execute([$user['id'],$name,$balance]); header('Location: index.php?success=1'); exit; }
    } elseif ($action === 'close') { $stmt=$pdo->prepare("UPDATE accounts SET status='inactive' WHERE id=? AND user_id=?"); $stmt->execute([(int)($_POST['id']??0),$user['id']]); header('Location: index.php'); exit; }
}
$stmt=$pdo->prepare('SELECT id,name,current_balance,status FROM accounts WHERE user_id=? ORDER BY id DESC'); $stmt->execute([$user['id']]); $accounts=$stmt->fetchAll();
$totalBalance=0; $activeCount=0; foreach($accounts as $account){$totalBalance+=(float)$account['current_balance'];if(($account['status']??'')==='active')$activeCount++;}
$page_title='Rekening'; require_once __DIR__ . '/../includes/header.php';
?>
