<section class="finance-card"><div class="card-head"><div><h2>Daftar rekening</h2><p>Ringkasan rekening dan statusnya.</p></div></div><?php if(!$accounts): ?><div class="empty">Belum ada rekening. Tambahkan rekening pertama kamu di atas.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Nama rekening</th><th>Saldo saat ini</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($accounts as $a): ?><tr><td><span class="primary-text"><?=htmlspecialchars($a['name'],ENT_QUOTES,'UTF-8')?></span></td><td><strong>Rp <?=number_format((float)$a['current_balance'],0,',','.')?></strong></td><td><span class="badge <?=$a['status']==='active'?'success':'neutral'?>"><?=htmlspecialchars($a['status'],ENT_QUOTES,'UTF-8')?></span></td><td><?php if($a['status']==='active'): ?><form method="post" onsubmit="return confirm('Nonaktifkan rekening ini?')"><input type="hidden" name="action" value="close"><input type="hidden" name="id" value="<?=(int)$a['id']?>"><button class="btn-small danger-btn" type="submit">Nonaktifkan</button></form><?php else: ?><span class="muted">Tidak ada aksi</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
